# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ANLAM ARAYIŞI TEMASINDA OKUMAYI YÖNETME SÜRECİ (TDE2.1)</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. İNCELER VE GÖRÜŞ OLUŞTURUR (TDE2.1.1)</text>\n  <text x="42" y="96" font-size="11" font-weight="bold" fill="#1e3a8a">• Okuma Amacını Belirleme:</text>\n  <text x="50" y="112" font-size="10.5" fill="#1e40af">Estetik zevk alma, bilgi edinme, empati kurma</text>\n  <text x="50" y="127" font-size="10.5" fill="#1e40af">veya dönemin zihniyetini/kültürünü tanıma.</text>\n  <text x="42" y="152" font-size="11" font-weight="bold" fill="#1e3a8a">• Metin Öncesi Tahminde Bulunma:</text>\n  <text x="50" y="168" font-size="10.5" fill="#1e40af">Başlık, görsel, yazar adı ve sayfa düzeninden</text>\n  <text x="50" y="183" font-size="10.5" fill="#1e40af">hareketle içerik, tür ve yazılış amacını tahmin etme;</text>\n  <text x="50" y="198" font-size="10.5" fill="#1e40af">okuma sonrasında tahminlerle metni karşılaştırma.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">2. STRATEJİ SEÇER VE SÜRDÜRÜR (TDE2.1.2)</text>\n  <text x="377" y="96" font-size="11" font-weight="bold" fill="#14532d">• Sesli Okuma Stratejisi:</text>\n  <text x="385" y="112" font-size="10.5" fill="#166534">Göz, kulak ve konuşma organlarının uyumu; vurgu,</text>\n  <text x="385" y="127" font-size="10.5" fill="#166534">tonlama, telaffuz ve edebî ahengi hissettirme.</text>\n  <text x="377" y="152" font-size="11" font-weight="bold" fill="#14532d">• Sessiz Okuma Stratejisi:</text>\n  <text x="385" y="168" font-size="10.5" fill="#166534">Dudak kıpırdatmadan ve mırıldanmadan göz-zihin</text>\n  <text x="385" y="183" font-size="10.5" fill="#166534">ilişkisiyle hızlı, derin ve odaklanmış kavrama.</text>\n  <text x="377" y="206" font-size="11" font-weight="bold" fill="#14532d">• Not Alarak ve Eleştirel Okuma:</text>\n  <text x="385" y="222" font-size="10.5" fill="#166534">Anahtar kavramları, açık ve örtük iletileri belirleme.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HİKÂYE TÜRÜNÜN YAPI UNSURLARI: "BİR KAVAK VE İNSANLAR" (HALDUN TANER)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">HİKÂYENİN DÖRT TEMEL YAPI UNSURU</text>\n  <text x="34" y="94" font-size="10.5" font-weight="bold" fill="#713f12">1. Olay Örgüsü ve Temel Çatışma:</text>\n  <text x="42" y="109" font-size="10" fill="#713f12">Kavağın kesilip telefon direği yapılması, direğin tekrar</text>\n  <text x="42" y="123" font-size="10" fill="#713f12">filizlenmesi, yakılması ve ibibik kuşunun intikamı.</text>\n  <text x="34" y="144" font-size="10.5" font-weight="bold" fill="#713f12">2. Kişiler (Varlık Kadrosu):</text>\n  <text x="42" y="159" font-size="10" fill="#713f12">Doğa dostu İhtiyar, kavak, çıkarcı Fabrikatör, kuşlar.</text>\n  <text x="34" y="180" font-size="10.5" font-weight="bold" fill="#713f12">3. Mekân ve 4. Zaman:</text>\n  <text x="42" y="195" font-size="10" fill="#713f12">Sahildeki yeşil yamaç → fabrika şantiyesi; mevsimsel</text>\n  <text x="42" y="209" font-size="10" fill="#713f12">döngü (yaz-güz-kış-bahar) ve yeniden doğuş.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">TEMA, İLETİ, ANLATICI VE ÜSLUP</text>\n  <text x="374" y="94" font-size="10.5" font-weight="bold" fill="#581c87">• Konu ve Tema (Doğa-Sanayi Çatışması):</text>\n  <text x="382" y="109" font-size="10" fill="#581c87">Maddi çıkar uğruna doğanın tahrip edilmesi ve</text>\n  <text x="382" y="123" font-size="10" fill="#581c87">tabiatın yaşama direncinin yenilmezliği.</text>\n  <text x="374" y="144" font-size="10.5" font-weight="bold" fill="#581c87">• Anlatıcı ve Bakış Açısı:</text>\n  <text x="382" y="159" font-size="10" fill="#581c87">Üçüncü kişi (o) anlatıcı; karakterlerin ve kavağın iç</text>\n  <text x="382" y="173" font-size="10" fill="#581c87">dünyasını bilen İlahi (Hâkim) bakış açısı.</text>\n  <text x="374" y="194" font-size="10.5" font-weight="bold" fill="#581c87">• Edebî Sanatlar ve Fabl Unsurları:</text>\n  <text x="382" y="209" font-size="10" fill="#581c87">Teşhis (kişileştirme), intak (konuşturma) ve ironi/mizah.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HİKÂYE (KURMACA) İLE ANI / HATIRA (GERÇEK YAŞANTI) KARŞILAŞTIRMASI</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">HİKÂYE ("BİR KAVAK VE İNSANLAR")</text>\n  <text x="42" y="96" font-size="10.5" fill="#1e3a8a">• Türü: Olay çevresinde gelişen edebî (kurmaca) metin</text>\n  <text x="42" y="118" font-size="10.5" fill="#1e3a8a">• Gerçeklik: Dış gerçeklik hayal gücüyle yeniden</text>\n  <text x="50" y="133" font-size="10.5" fill="#1e3a8a">kurgulanır (kurgusal gerçeklik).</text>\n  <text x="42" y="155" font-size="10.5" fill="#1e3a8a">• Yazılış Amacı: Estetik zevk uyandırmak, sezdirmek</text>\n  <text x="50" y="170" font-size="10.5" fill="#1e3a8a">(örtük ileti, imge ve sembol ağırlıklı).</text>\n  <text x="42" y="192" font-size="10.5" fill="#1e3a8a">• Anlatım: Öyküleyici ve betimleyici anlatım; 3. veya</text>\n  <text x="50" y="207" font-size="10.5" fill="#1e3a8a">1. kişi kurmaca anlatıcı.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">ANI ("NİHAYET BEKLEDİĞİMİZ BÜYÜK GÜN")</text>\n  <text x="377" y="96" font-size="10.5" fill="#7c2d12">• Türü: Kişisel hayatı konu alan öğretici metin</text>\n  <text x="377" y="118" font-size="10.5" fill="#7c2d12">• Gerçeklik: Yaşanmış olaylar üzerinden zaman</text>\n  <text x="385" y="133" font-size="10.5" fill="#7c2d12">geçtikten sonra bellekteki izleriyle aktarılır.</text>\n  <text x="377" y="155" font-size="10.5" fill="#7c2d12">• Yazılış Amacı: Tanıklık edilen döneme (Millî Mücadele</text>\n  <text x="385" y="170" font-size="10.5" fill="#7c2d12">ve İstanbul\'un kurtuluşu) ışık tutmak, paylaşmak.</text>\n  <text x="377" y="192" font-size="10.5" fill="#7c2d12">• Anlatım: Yazarın kendisi olan 1. kişi (ben) anlatıcı;</text>\n  <text x="385" y="207" font-size="10.5" fill="#7c2d12">içten, samimi, öznel ve tarihsel belge niteliğinde.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
